create extension if not exists pg_stat_statements;

create table lab_cpu as
select
    i as id,
    md5(i::text) as payload,
    (random() * 1000000)::int as v
from generate_series(1, 800000) as s(i);

create table lab_sort as
select
    i as id,
    md5(random()::text) || md5(i::text) as payload,
    (random() * 1000000)::int as v
from generate_series(1, 600000) as s(i);

create table lab_lock(id int primary key, payload text);
insert into lab_lock values (1, 'before');

analyze lab_cpu;
analyze lab_sort;
analyze lab_lock;
select pg_stat_statements_reset();
